  q('#m3-board').addEventListener('pointerup',e=>{if(!pointer||pointer.id!==e.pointerId)return;const p=pointer;pointer=null;if(q('#m3-board').hasPointerCapture(e.pointerId))q('#m3-board').releasePointerCapture(e.pointerId);ignoreClickUntil=performance.now()+350;if(p.committed)return;if(p.tokenId&&visual.board[p.index]?.id!==p.tokenId)return;const token=tokenAt(p.index);if(token){const transform=token.style.transform;if(transform)animate([token],[{transform},{transform:'translate(0,0) scale(1)'}],{duration:110});token.style.removeProperty('transform');}if(!p.moved||tool)choose(p.index);});

  q('#m3-board').addEventListener('pointercancel',()=>{pointer?.cell.querySelector('.m3-token')?.style.removeProperty('transform');pointer=null;});
  root.addEventListener('keydown',e=>{if(panel&&e.key==='Tab'){const bs=[...q('#m3-panel-card').querySelectorAll('button:not(:disabled)')],first=bs[0],last=bs.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}return;}if(e.key==='Escape'){e.preventDefault();e.stopPropagation();if(locked)return;if(panel==='help'||panel==='restart'){panel=session.game.status==='playing'?null:'result';render();}else if(tool){tool=null;render();}else onExit();return;}const cell=e.target.closest('[data-m3-index]');if(!cell||panel)return;const i=Number(cell.dataset.m3Index),d={ArrowLeft:-1,ArrowRight:1,ArrowUp:-7,ArrowDown:7}[e.key];if(d){e.preventDefault();if(m3Adjacent(i,i+d)&&visual.mask?.[i+d]!==0){focused=i+d;if(!locked)board();cellAt(focused)?.focus({preventScroll:true});}}else if(['Enter',' '].includes(e.key)){e.preventDefault();choose(i);}});
  return{show(next,context='为故乡带回重建材料'){effects.clearAll();session=next;visual=null;focused=next.game.board[focused]?focused:next.game.board.findIndex(Boolean);shown=true;locked=false;activeRuns.clear();root.dataset.phase='idle';root.dataset.activeRuns='0';root.setAttribute('aria-busy','false');chosen=null;hints=[];tool=null;inputBuffer.length=0;panel=next.game.status==='playing'?null:'result';root.hidden=false;q('#m3-purpose').textContent=context;render();status(next.game.level===1&&next.game.turn===0?'先合出火箭，再与螺旋桨组合。':'消除木箱，找回重建物资。');idleHint();},hide(){effects.clearAll();shown=false;root.hidden=true;panel=null;inputBuffer.length=0;chosen=null;tool=null;clearTimeout(hintTimer);},isBusy:()=>locked};
